(()=>{const root=document.getElementById('sv-sessions'),q=s=>root.querySelector(s);let event=Sessions.demo(),tab='sessions',selected=null,form=false,message='';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const date=d=>d.split('-').reverse().join('.');function save(){message='';render()}function action(f){try{f();message=''}catch(e){message=e.message}render()}
function render(){const rows=Sessions.leaderboard(event);root.innerHTML=`<main class="phone"><header><div class="brand">SV TEAM <span>ТРЕНЕР · ДЕМО</span></div><h1>${esc(event.name)}</h1><p>${esc(event.category)}</p><div class="badge">${event.closed?'Итоговый рейтинг':'Предварительный · старт продолжается'}</div></header><div class="body"><div class="tabs"><button data-tab="sessions" aria-pressed="${tab==='sessions'}">Сессии · ${event.sessions.length}</button><button data-tab="rank" aria-pressed="${tab==='rank'}">Общий рейтинг · ${rows.length}</button></div>${message?`<p class="error" role="alert">${esc(message)}</p>`:''}<div id="panel"></div><p class="note">Демонстрационные данные. Изменения действуют до перезагрузки. Опубликованные сессии в этом прототипе доступны только для просмотра.</p><button id="reset" class="quiet">Начать демо заново</button></div></main>`;root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=null;form=false;save()});q('#reset').onclick=()=>{event=Sessions.demo();selected=null;form=false;tab='sessions';save()};const panel=q('#panel');
if(tab==='rank'){panel.innerHTML=`<h2>Один старт — один рейтинг</h2><p class="note">Опубликовано ${event.sessions.filter(s=>s.published).length} из ${event.sessions.length} сессий. Все опубликованные попытки учитываются; у спортсмена одна строка.</p>${rows.length?rows.map(r=>`<div class="rank"><span class="place">${r.rank}</span><div><b>${esc(event.athletes.find(a=>a.id===r.athlete).name)}</b><small>${date(r.date)} · ${r.clock} · ${r.count} попыток</small></div><strong>${Sessions.format(r.time)}</strong></div>`).join(''):'<p>Опубликованных результатов пока нет.</p>'}<p class="note">Равные результаты: места 1 / 1 / 3 — предложенное правило.</p>`;return;}
if(form){panel.innerHTML=`<h2>Добавить сессию</h2><div id="new-session"><label for="session-date">Дата<input id="session-date" type="date" value="2026-10-02"></label><label for="session-time">Время начала<input id="session-time" type="time" value="19:00"></label><label for="session-group">Группа / название<input id="session-group" maxlength="80" placeholder="Например, Плавание · вечер"></label><p id="create-error" class="error" role="alert"></p><button id="create-session" class="primary" type="button">Создать сессию</button><button id="cancel" type="button">Отмена</button></div>`;q('#cancel').onclick=()=>{form=false;save()};q('#create-session').onclick=()=>{try{const s=Sessions.addSession(event,{date:q('#session-date').value,time:q('#session-time').value,group:q('#session-group').value});form=false;selected=s.id;save()}catch(e){q('#create-error').textContent=e.message}};return;}
if(selected){const s=event.sessions.find(s=>s.id===selected);const locked=s.published||event.closed;panel.innerHTML=`<button id="back" class="quiet">← Все сессии</button><h2>${esc(s.group)}</h2><p>${date(s.date)} · ${s.time} <span class="tag">${s.published?'Опубликовано':'Черновик'}</span></p>${s.entries.map((e,i)=>`<section class="participant"><b>${esc(event.athletes.find(a=>a.id===e.athlete).name)}</b>${e.attempts.map((v,j)=>`<label class="attempt">Попытка ${j+1}<input data-entry="${i}" data-attempt="${j}" aria-label="${esc(event.athletes.find(a=>a.id===e.athlete).name)}, попытка ${j+1}" inputmode="decimal" placeholder="00:33.10" value="${esc(v)}" ${locked?'readonly':''}></label>`).join('')}${!locked?`<button class="quiet" data-more="${i}">+ Попытка</button>`:''}</section>`).join('')}${!locked?`<label>Добавить участника<select id="athlete"><option value="">Выбери спортсмена</option>${event.athletes.filter(a=>!s.entries.some(e=>e.athlete===a.id)).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><button id="publish" class="primary">Опубликовать сессию</button>`:'<p class="note">Результаты этой сессии уже включены в общий рейтинг.</p>'}`;q('#back').onclick=()=>{selected=null;save()};root.querySelectorAll('[data-entry]').forEach(input=>{input.oninput=()=>{s.entries[+input.dataset.entry].attempts[+input.dataset.attempt]=input.value;input.setAttribute('aria-invalid',String(input.value!==''&&Sessions.parse(input.value)===null))};});root.querySelectorAll('[data-more]').forEach(b=>b.onclick=()=>{s.entries[+b.dataset.more].attempts.push('');save()});if(!locked){q('#athlete').onchange=e=>{if(e.target.value){s.entries.push({athlete:e.target.value,attempts:['']});save()}};q('#publish').onclick=()=>action(()=>{Sessions.publish(event,s.id);selected=null});}return;}
panel.innerHTML=`<div class="heading"><h2>Проведения старта</h2><span>${event.sessions.filter(s=>s.published).length}/${event.sessions.length} опубликовано</span></div>${event.sessions.map(s=>`<button class="session" data-session="${s.id}"><div class="session-top"><b>${esc(s.group)}</b><span class="tag">${s.published?'Опубликовано':'Черновик'}</span></div><div>${date(s.date)} · ${s.time}</div><small>${s.entries.length} участников · ${s.entries.reduce((n,e)=>n+e.attempts.length,0)} попыток</small></button>`).join('')}${!event.closed?'<button id="add-session" class="primary">+ Добавить сессию</button><button id="close">Закрыть старт</button>':'<p class="note">Старт закрыт. Общий рейтинг итоговый.</p>'}`;root.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{selected=b.dataset.session;save()});if(!event.closed){q('#add-session').onclick=()=>{form=true;save()};q('#close').onclick=()=>action(()=>Sessions.close(event));}}
render();})();
